using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalSixRoadDetails{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",PrefabPath="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas";
static readonly string[] Names={"polySurface817","polySurface812","polySurface540","polySurface884","polySurface808","polySurface839"};
static FinalSixRoadDetails(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalSixRoadDetails.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalSixRoadDetails.request");Run();}
static T Field<T>(object o,string name)=>(T)o.GetType().GetField(name).GetValue(o);
static object Call(Type t,string name,params object[] args)=>t.GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args);
static void Photo(Scene s,Vector3 p,Vector3 target,string name)=>Call(typeof(FinalPNGCityDetails),"Capture",s,p,target,name);
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var paint=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City PNG Markings.mat");int errors=ShaderUtil.GetShaderMessages(paint.shader).Count(m=>m.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeSixCurveDetails-"+stamp+".unity",true);File.Copy(PrefabPath,"FinalEnvironmentRoadBackup/BeforeSixCurveDetails-"+stamp+".prefab");var changes=new Dictionary<MeshFilter,Mesh>();var preview=new Dictionary<string,Vector3>();
foreach(var name in Names){var f=root.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name==name);var d=Call(typeof(FinalPNGCityDetails),"Read",f.sharedMesh);var p=Field<Vector3[]>(d,"p").Select(f.transform.TransformPoint).ToArray();var ids=Field<int[]>(d,"ids");var uv0=Field<Vector2[][]>(d,"uv")[0];var curve=Call(typeof(FinalBridgeStructures),"GetCurve",root,name);var rows=Field<IEnumerable>(curve,"rows");var points=new List<Vector3>();var dist=new List<float>();foreach(var row in rows){points.Add(Field<Vector3>(row,"p"));dist.Add(Field<float>(row,"s"));}float length=Field<float>(curve,"length"),repeats=Mathf.Max(1,Mathf.Round(length/40));float u0=uv0.Min(v=>v.x),u1=uv0.Max(v=>v.x);var mark=new Vector4[p.Length];for(int i=0;i<p.Length;i++){float best=float.PositiveInfinity,longitudinal=0;for(int k=1;k<points.Count;k++){var delta=points[k]-points[k-1];float t=Mathf.Clamp01(Vector3.Dot(p[i]-points[k-1],delta)/delta.sqrMagnitude);float distance=(p[i]-Vector3.Lerp(points[k-1],points[k],t)).sqrMagnitude;if(distance<best){best=distance;longitudinal=Mathf.Lerp(dist[k-1],dist[k],t);}}float v=longitudinal/length;mark[i]=new Vector4(16+Mathf.Clamp(Mathf.InverseLerp(u0,u1,uv0[i].x),.00001f,.99999f),v*repeats,v,repeats);}float sign=0;for(int k=0;k<ids.Length;k+=3){int a=ids[k],b=ids[k+1],c=ids[k+2];var ab=p[b]-p[a];var ac=p[c]-p[a];var ub=mark[b]-mark[a];var uc=mark[c]-mark[a];float det=ub.x*uc.y-ub.y*uc.x;if(Mathf.Abs(det)>.00001f){sign=(ab.x*ac.z-ab.z*ac.x)/det;break;}}if(sign<0)for(int i=0;i<mark.Length;i++){mark[i].y=repeats-mark[i].y;mark[i].z=1-mark[i].z;}var m=(Mesh)Call(typeof(FinalPNGCityDetails),"Copy",d,"PNG_CurveDetails_"+name);m.SetUVs(3,mark.ToList());if(!(bool)Call(typeof(FinalPNGCityDetails),"SameGeometry",d,m))throw new Exception("Geometry changed "+name);m=(Mesh)Call(typeof(FinalPNGCityDetails),"Store",m,m.name);changes.Add(f,m);preview[name]=(Vector3)curve.GetType().GetMethod("Point").Invoke(curve,new object[]{length*.45f});log.AppendLine("MARKED "+name+" curve length="+length+" lane width="+Field<float>(curve,"width")+" whole repeats="+repeats+" geometry/colliders unchanged");}
var prefab=PrefabUtility.LoadPrefabContents(PrefabPath);try{foreach(var c in changes){var path=AnimationUtility.CalculateTransformPath(c.Key.transform,root.transform);var pf=prefab.transform.Find(path).GetComponent<MeshFilter>();pf.sharedMesh=c.Value;pf.GetComponent<MeshRenderer>().sharedMaterial=paint;}PrefabUtility.SaveAsPrefabAsset(prefab,PrefabPath,out bool ok);if(!ok)throw new Exception("Prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(prefab);}foreach(var c in changes){c.Key.sharedMesh=c.Value;c.Key.GetComponent<MeshRenderer>().sharedMaterial=paint;PrefabUtility.RecordPrefabInstancePropertyModifications(c.Key);PrefabUtility.RecordPrefabInstancePropertyModifications(c.Key.GetComponent<MeshRenderer>());}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);foreach(var q in preview)Photo(scene,q.Value+Vector3.up*31,q.Value,"Marked-"+q.Key);
var group=root.transform.Find("Citywide Bus Stops - 20");var bus=group.GetChild(0);var stopRenderer=bus.GetComponent<Renderer>();var road=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial==paint&&!f.transform.IsChildOf(group)).OrderBy(f=>f.GetComponent<Renderer>().bounds.SqrDistance(bus.position)).First();var bounds=road.GetComponent<Renderer>().bounds;var dir=bounds.size.x>bounds.size.z?Vector3.right:Vector3.forward;var outwards=bus.position-bounds.center;outwards.y=0;outwards=bounds.size.x>bounds.size.z?new Vector3(0,0,Mathf.Sign(outwards.z)):new Vector3(Mathf.Sign(outwards.x),0,0);var camera=bus.position-outwards*10+dir*5+Vector3.up*5;for(int i=1;i<=3;i++)Photo(scene,camera,bus.position-outwards*3,"Stable-Bus-Paint-"+i);Photo(scene,bus.position-outwards*5+dir*3+Vector3.up*2,bus.position-outwards*3,"Close-Bus-Paint");log.AppendLine("SUCCESS: all six named curved roads mapped using the same atlas; centred bus caption; paint sampling runs consistently across overlay boundaries; smooth alpha wear instead of tiny transparent holes; shader errors=0; saved scene and prefab.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/SixRoadsAndStablePaint.txt",log.ToString());}
}
